-- 001_initial_schema.sql
-- Initial schema for sem3 Capstone: certificate-backed QR handoff authentication.
--
-- Canonical source. dbms/03_schema.sql is GENERATED from db/migrations/*.sql
-- (npm run db:ap:build). Do not edit the generated copy.
--
-- The migration runner (db/scripts/migrate.js) wraps each file in a single transaction,
-- so this file must not contain BEGIN/COMMIT.
--
-- Conventions
--   * Primary keys: uuid generated by gen_random_uuid() (built in since PostgreSQL 13), except
--     audit_events, which uses a bigint identity for cheap, ordered appends.
--   * All timestamps are timestamptz and are set from the database clock (now()), never a client.
--   * Secrets are never stored. Tokens, nonces and binding secrets are stored as SHA-256 digests
--     (bytea, 32 bytes). Passwords and recovery codes are stored as PHC-format KDF strings.
--   * Small closed value sets use text + CHECK rather than ENUM types, so values can be added
--     in a later migration without ALTER TYPE.
--   * "Write-once" columns (revoked_at, used_at, consumed_at) cannot be changed or cleared once
--     set; see the write_once() trigger function below.

-- ---------------------------------------------------------------------------------------------
-- Helper trigger functions
-- ---------------------------------------------------------------------------------------------

-- Rejects any UPDATE that changes a column after it has been set (non-NULL).
-- Usage: EXECUTE FUNCTION write_once('revoked_at')
CREATE FUNCTION write_once() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  column_name text := TG_ARGV[0];
  old_value jsonb := to_jsonb(OLD) -> column_name;
  new_value jsonb := to_jsonb(NEW) -> column_name;
BEGIN
  IF old_value IS NOT NULL AND old_value <> 'null'::jsonb AND new_value IS DISTINCT FROM old_value THEN
    RAISE EXCEPTION '%.% is write-once and cannot be changed after it is set', TG_TABLE_NAME, column_name
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------------------------
-- users: an account. The password is used only for the first sign-in on the phone and for
-- recovery; browser sign-in never uses it.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE users (
  id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Stored normalised (trimmed, lower case) by the application; the CHECK guarantees it.
  email         text        NOT NULL,
  display_name  text,
  -- PHC string, e.g. $scrypt$ln=17,r=8,p=1$<salt>$<hash>
  password_hash text        NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  -- Soft disable. Accounts are not hard-deleted by the application.
  disabled_at   timestamptz,

  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_email_normalised CHECK (email = lower(btrim(email))),
  CONSTRAINT users_email_shape CHECK (char_length(email) BETWEEN 3 AND 254 AND email LIKE '%_@_%'),
  CONSTRAINT users_display_name_length CHECK (display_name IS NULL OR char_length(display_name) BETWEEN 1 AND 100),
  CONSTRAINT users_password_hash_phc CHECK (password_hash ~ '^\$[a-z0-9-]+\$'),
  CONSTRAINT users_updated_after_created CHECK (updated_at >= created_at)
);

-- ---------------------------------------------------------------------------------------------
-- devices: a trusted phone enrolled by a user.
-- The phone authenticates its own API calls (list/revoke sessions) with a random bearer token;
-- only its SHA-256 digest is stored. Approving a login always requires a key signature instead.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE devices (
  id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name            text        NOT NULL,
  platform        text        NOT NULL,
  api_token_hash  bytea       NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  last_used_at    timestamptz,
  revoked_at      timestamptz,
  revoked_reason  text,

  CONSTRAINT devices_api_token_hash_key UNIQUE (api_token_hash),
  CONSTRAINT devices_name_length CHECK (char_length(name) BETWEEN 1 AND 64),
  CONSTRAINT devices_platform_valid CHECK (platform IN ('ios', 'android')),
  CONSTRAINT devices_api_token_hash_sha256 CHECK (octet_length(api_token_hash) = 32),
  CONSTRAINT devices_revocation_complete CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
  CONSTRAINT devices_revoked_reason_valid CHECK (revoked_reason IN ('user', 'lost', 'recovery', 'admin')),
  CONSTRAINT devices_revoked_after_created CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

-- Lists a user's devices, revokes all of them during recovery, and joins sessions to their user.
CREATE INDEX devices_user_id_idx ON devices (user_id);

CREATE TRIGGER devices_revoked_at_write_once
  BEFORE UPDATE OF revoked_at ON devices
  FOR EACH ROW EXECUTE FUNCTION write_once('revoked_at');

-- ---------------------------------------------------------------------------------------------
-- device_keys: public keys registered for a device. The matching private key lives in the
-- phone's Secure Enclave / Android Keystore and is never sent to the server.
-- Separate from devices because a device can rotate its key (Android invalidates biometric-bound
-- keys when fingerprints change) while keeping its identity and session history.
-- At most one active key per device.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE device_keys (
  id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  device_id        uuid        NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
  -- ES256 = ECDSA over P-256 with SHA-256 (the only curve the iOS Secure Enclave supports).
  algorithm        text        NOT NULL DEFAULT 'ES256',
  -- DER-encoded SubjectPublicKeyInfo, as exported by the platform and accepted by node:crypto.
  public_key_spki  bytea       NOT NULL,
  -- Where the platform reports the private key is held. Lets the server apply policy later.
  key_storage      text        NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_used_at     timestamptz,
  revoked_at       timestamptz,

  CONSTRAINT device_keys_public_key_spki_key UNIQUE (public_key_spki),
  CONSTRAINT device_keys_algorithm_valid CHECK (algorithm IN ('ES256')),
  -- A P-256 SPKI in DER form is exactly 91 bytes.
  CONSTRAINT device_keys_es256_spki_length CHECK (algorithm <> 'ES256' OR octet_length(public_key_spki) = 91),
  CONSTRAINT device_keys_storage_valid CHECK (key_storage IN ('secure_enclave', 'strongbox', 'tee', 'software', 'unknown')),
  CONSTRAINT device_keys_revoked_after_created CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

-- Integrity: a device has at most one active key. Also serves "revoke the active key".
CREATE UNIQUE INDEX device_keys_one_active_per_device
  ON device_keys (device_id) WHERE revoked_at IS NULL;

-- Foreign-key index: lets cascades and "all keys for a device" avoid a full scan.
CREATE INDEX device_keys_device_id_idx ON device_keys (device_id);

CREATE TRIGGER device_keys_revoked_at_write_once
  BEFORE UPDATE OF revoked_at ON device_keys
  FOR EACH ROW EXECUTE FUNCTION write_once('revoked_at');

-- ---------------------------------------------------------------------------------------------
-- enrollment_challenges: a one-time nonce the phone must sign to prove it holds the private key
-- it is registering (proof of possession). Issued after the initial password sign-in.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE enrollment_challenges (
  id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  nonce_hash   bytea       NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  consumed_at  timestamptz,

  CONSTRAINT enrollment_challenges_nonce_hash_sha256 CHECK (octet_length(nonce_hash) = 32),
  CONSTRAINT enrollment_challenges_expiry_window
    CHECK (expires_at > created_at AND expires_at <= created_at + interval '10 minutes'),
  CONSTRAINT enrollment_challenges_consumed_in_window
    CHECK (consumed_at IS NULL OR (consumed_at >= created_at AND consumed_at <= expires_at))
);

-- Cleanup job deletes expired rows by expiry time.
CREATE INDEX enrollment_challenges_expires_at_idx ON enrollment_challenges (expires_at);

CREATE TRIGGER enrollment_challenges_consumed_at_write_once
  BEFORE UPDATE OF consumed_at ON enrollment_challenges
  FOR EACH ROW EXECUTE FUNCTION write_once('consumed_at');

-- ---------------------------------------------------------------------------------------------
-- login_challenges: the short-lived, single-use challenge shown in the browser's QR code.
--
-- Lifecycle (enforced by CHECK constraints and the transition trigger):
--
--     pending ──approve──> approved ──browser completes──> consumed
--        └─────deny──────> denied
--
-- "Expired" is not stored: a challenge is expired when now() >= expires_at. Every guarded
-- UPDATE includes "expires_at > now()", so no background job is needed for correctness.
--
-- The user is not stored here: it is derived from decided_by_key_id -> device -> user.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE login_challenges (
  id                    uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- SHA-256 of the random nonce placed in the QR code.
  nonce_hash            bytea       NOT NULL,
  -- SHA-256 of the secret held in the requesting browser's HttpOnly cookie.
  browser_binding_hash  bytea       NOT NULL,
  status                text        NOT NULL DEFAULT 'pending',
  created_at            timestamptz NOT NULL DEFAULT now(),
  expires_at            timestamptz NOT NULL,
  -- Shown on the phone so the user can recognise the request (and spot a relay).
  requester_ip          inet,
  requester_user_agent  text,
  -- Set together when the phone approves or denies.
  decided_at            timestamptz,
  decided_by_key_id     uuid        REFERENCES device_keys (id) ON DELETE CASCADE,
  decision_signature    bytea,
  -- Set when the browser exchanges the approval for a session.
  consumed_at           timestamptz,

  CONSTRAINT login_challenges_status_valid
    CHECK (status IN ('pending', 'approved', 'denied', 'consumed')),
  CONSTRAINT login_challenges_nonce_hash_sha256 CHECK (octet_length(nonce_hash) = 32),
  CONSTRAINT login_challenges_binding_hash_sha256 CHECK (octet_length(browser_binding_hash) = 32),
  -- Matches LOGIN_CHALLENGE_TTL.maxSeconds (300) in packages/protocol.
  CONSTRAINT login_challenges_expiry_window
    CHECK (expires_at > created_at AND expires_at <= created_at + interval '5 minutes'),
  CONSTRAINT login_challenges_user_agent_length
    CHECK (requester_user_agent IS NULL OR char_length(requester_user_agent) <= 512),
  -- ECDSA P-256: 64 bytes raw (r||s) or up to 72 bytes DER.
  CONSTRAINT login_challenges_signature_length
    CHECK (decision_signature IS NULL OR octet_length(decision_signature) BETWEEN 64 AND 72),
  -- Each status has exactly the columns it needs.
  CONSTRAINT login_challenges_state_columns CHECK (
    (status = 'pending'
      AND decided_at IS NULL AND decided_by_key_id IS NULL AND decision_signature IS NULL
      AND consumed_at IS NULL)
    OR (status IN ('approved', 'denied')
      AND decided_at IS NOT NULL AND decided_by_key_id IS NOT NULL AND decision_signature IS NOT NULL
      AND consumed_at IS NULL)
    OR (status = 'consumed'
      AND decided_at IS NOT NULL AND decided_by_key_id IS NOT NULL AND decision_signature IS NOT NULL
      AND consumed_at IS NOT NULL)
  ),
  -- A decision must be made before the challenge expires; consumption follows the decision.
  CONSTRAINT login_challenges_decided_before_expiry
    CHECK (decided_at IS NULL OR (decided_at >= created_at AND decided_at <= expires_at)),
  CONSTRAINT login_challenges_consumed_after_decision
    CHECK (consumed_at IS NULL OR consumed_at >= decided_at)
);

-- Cleanup job deletes challenges some time after they expire. All other lookups use the primary key.
CREATE INDEX login_challenges_expires_at_idx ON login_challenges (expires_at);

-- Only these transitions are allowed: pending->approved, pending->denied, approved->consumed.
-- Identity, nonce, binding, and expiry columns are immutable; decision columns are immutable once set.
CREATE FUNCTION login_challenges_enforce_transition() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.nonce_hash IS DISTINCT FROM OLD.nonce_hash
     OR NEW.browser_binding_hash IS DISTINCT FROM OLD.browser_binding_hash
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
     OR NEW.requester_ip IS DISTINCT FROM OLD.requester_ip
     OR NEW.requester_user_agent IS DISTINCT FROM OLD.requester_user_agent THEN
    RAISE EXCEPTION 'login_challenges: immutable column changed'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT ((OLD.status = 'pending' AND NEW.status IN ('approved', 'denied'))
          OR (OLD.status = 'approved' AND NEW.status = 'consumed')) THEN
    RAISE EXCEPTION 'login_challenges: illegal transition % -> %', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status <> 'pending'
     AND (NEW.decided_at IS DISTINCT FROM OLD.decided_at
          OR NEW.decided_by_key_id IS DISTINCT FROM OLD.decided_by_key_id
          OR NEW.decision_signature IS DISTINCT FROM OLD.decision_signature) THEN
    RAISE EXCEPTION 'login_challenges: decision is immutable once recorded'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER login_challenges_transition
  BEFORE UPDATE ON login_challenges
  FOR EACH ROW EXECUTE FUNCTION login_challenges_enforce_transition();

-- ---------------------------------------------------------------------------------------------
-- browser_sessions: a signed-in browser, created by consuming an approved login challenge.
-- The browser holds a random token in an HttpOnly cookie; only its SHA-256 digest is stored.
-- The owning user is derived through approved_by_device_id -> devices.user_id.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE browser_sessions (
  id                     uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- One session per challenge (UNIQUE): the database-level backstop against replay.
  -- SET NULL because challenges are purged after they expire, while sessions live longer.
  login_challenge_id     uuid        REFERENCES login_challenges (id) ON DELETE SET NULL,
  approved_by_device_id  uuid        NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
  token_hash             bytea       NOT NULL,
  created_at             timestamptz NOT NULL DEFAULT now(),
  last_seen_at           timestamptz NOT NULL DEFAULT now(),
  -- Absolute lifetime. The idle timeout is applied in queries using last_seen_at.
  expires_at             timestamptz NOT NULL,
  ip                     inet,
  user_agent             text,
  revoked_at             timestamptz,
  revoked_reason         text,

  CONSTRAINT browser_sessions_login_challenge_id_key UNIQUE (login_challenge_id),
  CONSTRAINT browser_sessions_token_hash_key UNIQUE (token_hash),
  CONSTRAINT browser_sessions_token_hash_sha256 CHECK (octet_length(token_hash) = 32),
  CONSTRAINT browser_sessions_lifetime
    CHECK (expires_at > created_at AND expires_at <= created_at + interval '30 days'),
  CONSTRAINT browser_sessions_last_seen_after_created CHECK (last_seen_at >= created_at),
  CONSTRAINT browser_sessions_user_agent_length CHECK (user_agent IS NULL OR char_length(user_agent) <= 512),
  CONSTRAINT browser_sessions_revocation_complete CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
  CONSTRAINT browser_sessions_revoked_reason_valid
    CHECK (revoked_reason IN ('signed_out', 'revoked_by_phone', 'device_revoked', 'recovery', 'admin')),
  CONSTRAINT browser_sessions_revoked_after_created CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

-- Lists a user's sessions (via their devices), revokes all sessions a device approved,
-- and serves the foreign key.
CREATE INDEX browser_sessions_device_idx ON browser_sessions (approved_by_device_id);

-- Retention purge: a session has ended at the earlier of expiry and revocation.
-- LEAST() ignores NULLs, so this is expires_at for sessions that were never revoked.
CREATE INDEX browser_sessions_ended_at_idx ON browser_sessions ((LEAST(expires_at, revoked_at)));

CREATE TRIGGER browser_sessions_revoked_at_write_once
  BEFORE UPDATE OF revoked_at ON browser_sessions
  FOR EACH ROW EXECUTE FUNCTION write_once('revoked_at');

-- ---------------------------------------------------------------------------------------------
-- Recovery codes. Codes are issued in batches of 10, shown to the user once, and stored hashed.
-- Generating a new batch revokes the previous one. At most one active batch per user.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE recovery_code_batches (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  revoked_at  timestamptz,

  CONSTRAINT recovery_code_batches_revoked_after_created CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

-- Integrity: one active batch per user. Also serves "find the user's active codes".
CREATE UNIQUE INDEX recovery_code_batches_one_active_per_user
  ON recovery_code_batches (user_id) WHERE revoked_at IS NULL;

CREATE TRIGGER recovery_code_batches_revoked_at_write_once
  BEFORE UPDATE OF revoked_at ON recovery_code_batches
  FOR EACH ROW EXECUTE FUNCTION write_once('revoked_at');

CREATE TABLE recovery_codes (
  id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  batch_id   uuid        NOT NULL REFERENCES recovery_code_batches (id) ON DELETE CASCADE,
  -- PHC string from a slow KDF: codes have limited entropy, so a fast hash would be brute-forceable.
  code_hash  text        NOT NULL,
  used_at    timestamptz,

  CONSTRAINT recovery_codes_code_hash_phc CHECK (code_hash ~ '^\$[a-z0-9-]+\$')
);

-- Fetches the codes of a batch when verifying a recovery attempt; serves the foreign key.
CREATE INDEX recovery_codes_batch_id_idx ON recovery_codes (batch_id);

CREATE TRIGGER recovery_codes_used_at_write_once
  BEFORE UPDATE OF used_at ON recovery_codes
  FOR EACH ROW EXECUTE FUNCTION write_once('used_at');

-- ---------------------------------------------------------------------------------------------
-- audit_events: append-only log of security-relevant actions.
-- No foreign keys on purpose: the log must survive deletion of the rows it describes, and
-- ON DELETE SET NULL would require updating rows that are meant to be immutable.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE audit_events (
  id           bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at  timestamptz NOT NULL DEFAULT now(),
  event_type   text        NOT NULL,
  user_id      uuid,
  device_id    uuid,
  session_id   uuid,
  challenge_id uuid,
  ip           inet,
  user_agent   text,
  details      jsonb       NOT NULL DEFAULT '{}'::jsonb,

  CONSTRAINT audit_events_event_type_valid CHECK (event_type IN (
    'user.registered',
    'user.password_login_succeeded',
    'user.password_login_failed',
    'user.password_changed',
    'device.enrolled',
    'device.key_rotated',
    'device.revoked',
    'login.challenge_created',
    'login.approved',
    'login.denied',
    'login.signature_invalid',
    'login.replay_rejected',
    'session.created',
    'session.revoked',
    'session.signed_out',
    'recovery.codes_generated',
    'recovery.code_used',
    'recovery.failed',
    'recovery.completed'
  )),
  CONSTRAINT audit_events_details_object CHECK (jsonb_typeof(details) = 'object'),
  CONSTRAINT audit_events_user_agent_length CHECK (user_agent IS NULL OR char_length(user_agent) <= 512)
);

-- Account activity view on the phone: newest events for one user, keyset-paginated.
CREATE INDEX audit_events_user_time_idx ON audit_events (user_id, occurred_at DESC, id DESC);

-- Retention purge by time. Rows are appended in time order, so a tiny BRIN index is enough.
CREATE INDEX audit_events_occurred_at_brin ON audit_events USING brin (occurred_at);

CREATE FUNCTION audit_events_forbid_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit_events is append-only' USING ERRCODE = 'check_violation';
END;
$$;

CREATE TRIGGER audit_events_append_only
  BEFORE UPDATE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION audit_events_forbid_update();
